/// <summary>
/// CB625_TMSSOPickingListExtraction
/// Class responsible for populating the TMS engine temp table (calculation table) for delivery note
/// </summary>
internal final class METTMSEngineLinesTmpBuilder_PickingList extends METTMSEngineLinesTmpBuilder
{
    boolean     isInternalCrossDockOrder;
    boolean     isCSDWarehouse;

}

Method.Source:
/// <summary>
/// New method
/// </summary>
/// <param name = "_salesTable">SalesTable record</param>
void new(SalesTable _salesTable)
{
    this.init(_salesTable);
}

/// <summary>
/// initialize default parameters
/// </summary>
/// <param name = "_salesTable">SalesTable record</param>
protected void init(SalesTable _salesTable)
{
    super(_salesTable);
    METSalesTable   metSalesTable = METSalesTable::findByRefRecId(salesTable.RecId);
    isInternalCrossDockOrder    = metSalesTable.InternalCrossDockOrder;
}

/// <summary>
/// initialize default parameters
/// </summary>
/// <param name = "_salesLine"><c>SalesLine</c> record</param>
protected void initSalesLineVariables(SalesLine _salesLine)
{
    super(_salesLine);
    isCSDWarehouse  = inventLocation.METCSDWarehouse;
}

/// <summary>
/// Manages the lineShipQty variable
/// </summary>
/// <param name = "_salesLine">Sales order line</param>
/// <returns>Sales order quantity</returns>
protected SalesOrderedQty lineShipQty(SalesLine   _salesLine)
{
    if (isInternalCrossDockOrder || isCSDWarehouse)
    {
        return _salesLine.SalesQty
            - _salesLine.pickedInTotalSalesUnit()
            - _salesLine.deliveredInTotal();
    }
    else
    //if (!isInternalCrossDockOrder && !isCSDWarehouse)
    {
        return _salesLine.pickedInTotalSalesUnit();
    }
}
